<?php defined('ABSPATH')||exit;$theme=get_option('eaiw_theme','dark');$search=sanitize_text_field(wp_unslash($_GET['s']??''));$filter_status=sanitize_key($_GET['status']??'');$filter_priority=absint($_GET['priority']??0);$negative=EAIW_Chat_Feedback::negative(20);$items=EAIW_Support_Request::recent(['limit'=>100,'search'=>$search,'status'=>$filter_status,'priority'=>$filter_priority]);$experts=get_users(['role'=>'eaiw_support']);$labels=['new'=>'جدید','open'=>'در حال بررسی','answered'=>'پاسخ داده‌شده','closed'=>'بسته‌شده'];?><div class="wrap eaiw-nebula-wrap <?php echo $theme==='light'?'eaiw-light':'';?>"><div class="eaiw-nebula-bg"></div><div class="eaiw-topbar"><div class="eaiw-brand"><div class="eaiw-logo">?</div><div><h1>صندوق پشتیبانی</h1><p>درخواست‌های کاربران را بررسی و پاسخ دهید.</p></div></div><a class="eaiw-btn eaiw-btn-ghost" href="<?php echo esc_url(admin_url('admin.php?page=eaiw-nebula'));?>">بازگشت</a></div><?php if($negative):?><div class="eaiw-card eaiw-negative-feedback"><h3>پاسخ‌های نیازمند بررسی</h3><p class="eaiw-help">این پاسخ‌ها بیشترین نیاز به بازبینی را دارند و می‌توانند برای اصلاح FAQ یا خرد سایت استفاده شوند.</p><?php foreach($negative as $f):?><div class="eaiw-feedback-row"><span class="eaiw-badge red">نیازمند بهبود</span><span><?php echo esc_html(mb_strimwidth($f['message'],0,220,'…'));?></span><small><?php echo esc_html($f['created_at']);?></small><button type="button" class="eaiw-btn eaiw-btn-ghost eaiw-feedback-faq" data-id="<?php echo (int)$f['id'];?>">ویرایش و افزودن به FAQ</button></div><?php endforeach;?></div><?php endif;?>
<div class="eaiw-card"><form method="get" class="eaiw-support-filter"><input type="hidden" name="page" value="eaiw-support"><input class="eaiw-input" name="s" value="<?php echo esc_attr($search);?>" placeholder="جست‌وجو در درخواست‌ها"><select class="eaiw-select" name="status"><option value="">همه وضعیت‌ها</option><?php foreach($labels as $lk=>$ln):?><option value="<?php echo esc_attr($lk);?>" <?php selected($filter_status,$lk);?>><?php echo esc_html($ln);?></option><?php endforeach;?></select><select class="eaiw-select" name="priority"><option value="0">همه اولویت‌ها</option><option value="1" <?php selected($filter_priority,1);?>>فوری</option><option value="2" <?php selected($filter_priority,2);?>>عادی</option><option value="3" <?php selected($filter_priority,3);?>>کم‌اهمیت</option></select><button class="eaiw-btn eaiw-btn-primary">جست‌وجو</button></form><div class="eaiw-support-list"><?php if(!$items):?><div class="eaiw-empty">درخواستی ثبت نشده است.</div><?php else:foreach($items as $x):?><article class="eaiw-support-item"><div class="eaiw-toolbar"><strong>#<?php echo (int)$x['id'];?> — <?php echo esc_html($x['name']?:'کاربر ناشناس');?></strong><span class="eaiw-badge <?php echo $x['status']==='answered'?'green':($x['status']==='closed'?'purple':'cyan');?>"><?php echo esc_html($labels[$x['status']]??$x['status']);?></span></div><p class="eaiw-help">تماس: <?php echo esc_html($x['contact']?:'ثبت نشده');?> · <?php echo esc_html($x['created_at']);?></p><?php $history=EAIW_Support_Request::history($x['id']); if($history):?><details class="eaiw-support-history"><summary>تاریخچه پاسخ‌ها (<?php echo count($history);?>)</summary><?php foreach($history as $h):$u=get_userdata((int)$h['user_id']);?><div><strong><?php echo esc_html($u?$u->display_name:'کارشناس');?></strong><small><?php echo esc_html($h['created_at']);?></small><p><?php echo nl2br(esc_html($h['response']));?></p></div><?php endforeach;?></details><?php endif;?><?php if(!empty($x['audio_url'])):?><audio controls src="<?php echo esc_url($x['audio_url']);?>" style="width:100%;margin:8px 0"></audio><?php endif;?><div class="eaiw-support-message"><?php echo nl2br(esc_html($x['message']));?></div><textarea class="eaiw-textarea eaiw-support-response" data-id="<?php echo (int)$x['id'];?>" placeholder="پاسخ کارشناس..."><?php echo esc_textarea($x['response']??'');?></textarea><div class="eaiw-toolbar"><select class="eaiw-select eaiw-support-assigned" data-id="<?php echo (int)$x['id'];?>"><option value="0">بدون واگذاری</option><?php foreach($experts as $expert):?><option value="<?php echo (int)$expert->ID;?>" <?php selected((int)$x['assigned_user'],(int)$expert->ID);?>><?php echo esc_html($expert->display_name);?></option><?php endforeach;?></select><select class="eaiw-select eaiw-support-status" data-id="<?php echo (int)$x['id'];?>"><option value="new" <?php selected($x['status'],'new');?>>جدید</option><option value="open" <?php selected($x['status'],'open');?>>در حال بررسی</option><option value="answered" <?php selected($x['status'],'answered');?>>پاسخ داده‌شده</option><option value="closed" <?php selected($x['status'],'closed');?>>بسته‌شده</option></select><button class="eaiw-btn eaiw-btn-primary eaiw-support-save" data-id="<?php echo (int)$x['id'];?>">ذخیره پاسخ</button></div></article><?php endforeach;endif;?></div></div><script>jQuery(function($){$('.eaiw-feedback-faq').on('click',function(){const b=$(this);b.prop('disabled',true).text('در حال افزودن...');const q=prompt('پرسش FAQ را وارد کنید:','پرسش ثبت‌شده از بازخورد');if(!q)return;const a=prompt('پاسخ FAQ را وارد کنید:','');if(!a)return;$.post(EAIW.ajax,{action:'eaiw_feedback_faq',id:b.data('id'),question:q,answer:a,_ajax_nonce:EAIW.nonce},function(r){if(r.success){b.text('افزوده شد');}else{b.prop('disabled',false).text('افزودن به FAQ');alert(r.data||'عملیات انجام نشد.');}});});$('.eaiw-support-save').on('click',function(){const b=$(this),id=b.data('id'),box=$('.eaiw-support-response[data-id='+id+']'),st=$('.eaiw-support-status[data-id='+id+']');b.prop('disabled',true).text('در حال ذخیره...');$.post(EAIW.ajax,{action:'eaiw_support_update',id:id,response:box.val(),status:st.val(),assigned_user:$('.eaiw-support-assigned[data-id='+id+']').val(),_ajax_nonce:EAIW.nonce},function(r){b.prop('disabled',false).text('ذخیره پاسخ');if(r.success)location.reload();else alert(r.data||'عملیات انجام نشد.');});});});</script></div>
